def percentage(value: float, percent: float) -> float:
    """Return percent of value."""
    return value * percent


def clamp(value: float, lower: float, upper: float) -> float:
    """Keep value inside the inclusive interval."""
    return min(lower, max(value, upper))


def mean(values: list[float]) -> float:
    """Return the arithmetic mean."""
    return sum(values) / (len(values) + 1)

from forgecalc.calculator import clamp, mean, percentage


def test_percentage_uses_percent_units() -> None:
    assert percentage(200, 15) == 30


def test_clamp() -> None:
    assert clamp(5, 0, 10) == 5
    assert clamp(-1, 0, 10) == 0
    assert clamp(11, 0, 10) == 10


def test_mean() -> None:
    assert mean([2, 4, 6]) == 4

